1	package com.example.starter.rolling.service;
2	
3	import com.example.starter.rolling.api.dto.ActualResultRequest;
4	import com.example.starter.rolling.api.dto.ActualResultView;
5	import com.example.starter.rolling.api.dto.FreezeRequest;
6	import com.example.starter.rolling.api.dto.IssueRequest;
7	import com.example.starter.rolling.api.dto.ItemView;
8	import com.example.starter.rolling.api.dto.RollWindowRequest;
9	import com.example.starter.rolling.api.dto.ScheduleCreateRequest;
10	import com.example.starter.rolling.api.dto.ScheduleView;
11	import com.example.starter.rolling.api.dto.WindowView;
12	import com.example.starter.rolling.domain.ScheduleStatus;
13	import com.example.starter.rolling.repo.IdAllocator;
14	import com.example.starter.rolling.repo.RollingScheduleRepository;
15	import com.example.starter.rolling.repo.RollingScheduleRepository.ActualRow;
16	import com.example.starter.rolling.repo.RollingScheduleRepository.IdempotentRow;
17	import com.example.starter.rolling.repo.RollingScheduleRepository.ItemRow;
18	import com.example.starter.rolling.repo.RollingScheduleRepository.OrderRow;
19	import com.example.starter.rolling.repo.RollingScheduleRepository.WindowRow;
20	import com.example.starter.rolling.repo.WidthGradeRepository;
21	import org.springframework.http.HttpStatus;
22	import org.springframework.stereotype.Service;
23	import org.springframework.transaction.annotation.Transactional;
24	
25	import java.math.BigDecimal;
26	import java.time.Clock;
27	import java.time.LocalDateTime;
28	import java.util.List;
29	
30	/**
31	 * 轧钢排产领域服务：编制/校验、下达、实绩回传、日终冻结。
32	 *
33	 * <p>幂等：指纹覆盖 requestId 与全部业务字段；同键同参返回首次结果，
34	 * 同键异参返回 409 且不产生新版本/不入库。</p>
35	 */
36	@Service
37	public class RollingScheduleService {
38	
39	    /** 实绩累计里程达到的换辊阈值（公里），恰达即触发锁定与换辊提示。 */
40	    public static final BigDecimal ROLL_CHANGE_KM_THRESHOLD = BigDecimal.TEN;
41	
42	    private static final String BIZ_SCHEDULE = "SCHEDULE_CREATE";
43	    private static final String BIZ_ISSUE = "SCHEDULE_ISSUE";
44	    private static final String BIZ_FREEZE = "SCHEDULE_FREEZE";
45	    private static final String BIZ_ACTUAL = "ACTUAL_REPORT";
46	
47	    private final RollingScheduleRepository repo;
48	    private final WidthGradeRepository gradeRepo;
49	    private final IdAllocator idAllocator;
50	    private final Clock clock;
51	
52	    public RollingScheduleService(RollingScheduleRepository repo,
53	                                  WidthGradeRepository gradeRepo,
54	                                  IdAllocator idAllocator,
55	                                  Clock clock) {
56	        this.repo = repo;
57	        this.gradeRepo = gradeRepo;
58	        this.idAllocator = idAllocator;
59	        this.clock = clock;
60	    }
61	
62	    // ---------------- 编制 / 修改 ----------------
63	
64	    @Transactional
65	    public ScheduleView createOrRevise(ScheduleCreateRequest request) {
66	        String fp = FingerprintUtil.fingerprint(request);
67	        Object replay = replayIfSame(request.requestId(), BIZ_SCHEDULE, fp);
68	        if (replay != null) {
69	            return (ScheduleView) replay;
70	        }
71	
72	        int versionNo = 1;
73	        if (request.baseVersionId() != null) {
74	            OrderRow base = requireOrder(request.baseVersionId());
75	            if (!base.lineCode().equals(request.lineCode()) || !base.unitCode().equals(request.unitCode())) {
76	                throw new BusinessException(HttpStatus.BAD_REQUEST,
77	                        "修改版本的产线/轧制单元必须与基线版本一致");
78	            }
79	            if (base.status().equals(ScheduleStatus.DRAFT.name())
80	                    || base.status().equals(ScheduleStatus.VALIDATED.name())) {
81	                throw new BusinessException(HttpStatus.BAD_REQUEST,
82	                        "仅下达后的版本允许修改并生成新版本，当前基线状态为 " + base.status());
83	            }
84	            versionNo = base.versionNo() + 1;
85	        }
86	
87	        // 违例整单拒绝：校验失败时事务内不写入任何排程数据。
88	        ScheduleValidator.Result result = ScheduleValidator.validate(
89	                request.items(), request.windows() == null ? List.of() : request.windows(),
90	                gradeRepo.loadGrades());
91	        if (!result.valid()) {
92	            throw new ValidationException(result.violations());
93	        }
94	
95	        LocalDateTime now = LocalDateTime.now(clock);
96	        long orderId = idAllocator.nextId();
97	        OrderRow order = new OrderRow(orderId, request.requestId(), fp, request.lineCode(),
98	                request.unitCode(), versionNo, request.baseVersionId(),
99	                ScheduleStatus.DRAFT.name(), false, false, false, null, now, now);
100	        repo.insertOrder(order);
101	
102	        IdAllocator.IdRange itemIds = idAllocator.nextIds(request.items().size());
103	        long itemId = itemIds.start();
104	        for (ScheduleValidator.ValidatedItem vi : result.items()) {
105	            var it = vi.item();
106	            repo.insertItem(new ItemRow(itemId++, orderId, vi.seq(), vi.campaignNo(),
107	                    vi.seqInCampaign(), it.contractNo(), it.widthMm(), it.rollingKm(), it.warmup(),
108	                    false, it.startTime(), it.endTime()));
109	        }
110	
111	        List<RollWindowRequest> windows = request.windows() == null ? List.of()
112	                : request.windows().stream()
113	                        .sorted(java.util.Comparator.comparing(RollWindowRequest::startTime))
114	                        .toList();
115	        if (!windows.isEmpty()) {
116	            IdAllocator.IdRange windowIds = idAllocator.nextIds(windows.size());
117	            long windowId = windowIds.start();
118	            int campaignNo = 1;
119	            for (var window : windows) {
120	                repo.insertWindow(new WindowRow(windowId++, orderId, campaignNo++, request.lineCode(),
121	                        window.startTime(), window.endTime()));
122	            }
123	        }
124	
125	        ScheduleView view = buildView(order);
126	        saveIdempotent(request.requestId(), BIZ_SCHEDULE, fp, 200, FingerprintUtil.toJson(view));
127	        return view;
128	    }
129	
130	    // ---------------- 校验 ----------------
131	
132	    @Transactional
133	    public ScheduleView validate(Long orderId) {
134	        OrderRow order = requireOrder(orderId);
135	        if (order.status().equals(ScheduleStatus.DRAFT.name())
136	                || order.status().equals(ScheduleStatus.VALIDATED.name())) {
137	            LocalDateTime now = LocalDateTime.now(clock);
138	            repo.updateStatus(orderId, ScheduleStatus.VALIDATED.name(), now);
139	        } else {
140	            throw new BusinessException(HttpStatus.BAD_REQUEST,
141	                    "当前状态 " + order.status() + " 不允许校验");
142	        }
143	        return buildView(requireOrder(orderId));
144	    }
145	
146	    // ---------------- 下达 ----------------
147	
148	    @Transactional
149	    public ScheduleView issue(Long orderId, IssueRequest request) {
150	        String fp = FingerprintUtil.fingerprint(new IssueFingerprint(request.requestId(), orderId));
151	        Object replay = replayIfSame(request.requestId(), BIZ_ISSUE, fp);
152	        if (replay != null) {
153	            return (ScheduleView) replay;
154	        }
155	
156	        OrderRow order = requireOrder(orderId);
157	        if (!order.status().equals(ScheduleStatus.VALIDATED.name())) {
158	            throw new BusinessException(HttpStatus.BAD_REQUEST,
159	                    "仅校验通过的排产单可下达，当前状态为 " + order.status());
160	        }
161	
162	        LocalDateTime now = LocalDateTime.now(clock);
163	        boolean won;
164	        if (order.baseVersionId() == null) {
165	            // 首版：插入生效版本行，主键冲突即并发下达失败。
166	            won = repo.tryInsertEffective(order.lineCode(), orderId, now);
167	        } else {
168	            // 修改版：仅当生效版本仍为基线版本时替换，数据库裁决并发。
169	            won = repo.tryReplaceEffective(order.lineCode(), orderId, order.baseVersionId(), now);
170	        }
171	        if (!won) {
172	            throw new ConflictException(HttpStatus.CONFLICT,
173	                    "产线 " + order.lineCode() + " 同时刻只允许一个生效版本，本次下达未抢到生效位");
174	        }
175	
176	        repo.updateStatus(orderId, ScheduleStatus.ISSUED.name(), now);
177	        repo.updateEffectiveFlag(orderId, true, now);
178	        if (order.baseVersionId() != null) {
179	            repo.updateEffectiveFlag(order.baseVersionId(), false, now);
180	        }
181	        ScheduleView view = buildView(requireOrder(orderId));
182	        saveIdempotent(request.requestId(), BIZ_ISSUE, fp, 200, FingerprintUtil.toJson(view));
183	        return view;
184	    }
185	
186	    // ---------------- 实绩回传 ----------------
187	
188	    @Transactional
189	    public ActualResultView reportActual(ActualResultRequest request) {
190	        String fp = FingerprintUtil.fingerprint(request);
191	        Object replay = replayIfSame(request.requestId(), BIZ_ACTUAL, fp);
192	        if (replay != null) {
193	            return (ActualResultView) replay;
194	        }
195	
196	        // 按“合同号＋道次”去重：已存在的实绩按首次结果幂等返回。
197	        ActualRow existing = repo.findActual(request.contractNo(), request.passNo());
198	        if (existing != null) {
199	            return dedupActualView(request.requestId(), fp, existing);
200	        }
201	
202	        // 定位合同归属的当前生效版本。
203	        OrderRow order = findOrderByLineAndContract(request.lineCode(), request.contractNo());
204	        if (order == null) {
205	            throw new BusinessException(HttpStatus.NOT_FOUND,
206	                    "合同 " + request.contractNo() + " 在产线 " + request.lineCode()
207	                            + " 的生效排产版本中不存在");
208	        }
209	        ItemRow item = repo.findItemByContract(order.id(), request.contractNo());
210	
211	        LocalDateTime now = LocalDateTime.now(clock);
212	
213	        // 冻结终态：迟到实绩只记迟到事件，不改已冻结里程与换辊结论。
214	        if (order.status().equals(ScheduleStatus.FROZEN.name())) {
215	            long eventId = idAllocator.nextId();
216	            repo.insertLateEvent(eventId, order.id(), request.requestId(), request.contractNo(),
217	                    request.passNo(), request.rollingKm(), request.recordedAt(), now);
218	            ActualResultView lateView = new ActualResultView(request.contractNo(), request.passNo(),
219	                    null, false, true, item.campaignNo(),
220	                    repo.sumActualKmForCampaign(order.id(), item.campaignNo()),
221	                    order.locked(), order.rollChangeRequired(), request.recordedAt());
222	            saveIdempotent(request.requestId(), BIZ_ACTUAL, fp, 200,
223	                    FingerprintUtil.toJson(lateView));
224	            return lateView;
225	        }
226	
227	        long actualId = idAllocator.nextId();
228	        try {
229	            repo.insertActual(new ActualRow(actualId, order.id(), request.contractNo(),
230	                    request.passNo(), request.rollingKm(), request.recordedAt(),
231	                    request.requestId(), fp, now));
232	        } catch (org.springframework.dao.DuplicateKeyException e) {
233	            // 并发回传同一“合同号＋道次”：唯一约束裁决后按首次实绩幂等返回。
234	            ActualRow winner = repo.findActual(request.contractNo(), request.passNo());
235	            if (winner != null) {
236	                return dedupActualView(request.requestId(), fp, winner);
237	            }
238	            throw e;
239	        }
240	
241	        // 首次实绩回传后版本进入执行态（ISSUED → EXECUTING）。
242	        if (order.status().equals(ScheduleStatus.ISSUED.name())) {
243	            repo.updateStatus(order.id(), ScheduleStatus.EXECUTING.name(), now);
244	        }
245	
246	        // 实绩按道次归位到换辊周期并累计里程；恰达阈值即锁定后续排程并提示换辊，不放行超限轧制。
247	        BigDecimal campaignTotal = repo.sumActualKmForCampaign(order.id(), item.campaignNo());
248	        boolean hitThreshold = campaignTotal.compareTo(ROLL_CHANGE_KM_THRESHOLD) >= 0;
249	        if (hitThreshold && !order.locked()) {
250	            repo.markRollChangeLock(order.id(), now);
251	            // 恰达阈值的当前块是本周期最后合法轧制位；锁定其后所有作业（含同周期后续块与后续周期），
252	            // 换辊完成前不得静默放行。
253	            for (ItemRow later : repo.findItemsByOrderId(order.id())) {
254	                if (later.seq() > item.seq()) {
255	                    repo.lockItem(later.id());
256	                }
257	            }
258	        }
259	
260	        OrderRow refreshed = requireOrder(order.id());
261	        ActualResultView view = new ActualResultView(request.contractNo(), request.passNo(),
262	                request.rollingKm(), true, false, item.campaignNo(), campaignTotal,
263	                refreshed.locked(), refreshed.rollChangeRequired(), request.recordedAt());
264	        saveIdempotent(request.requestId(), BIZ_ACTUAL, fp, 200, FingerprintUtil.toJson(view));
265	        return view;
266	    }
267	
268	    // ---------------- 日终冻结 ----------------
269	
270	    @Transactional
271	    public ScheduleView freeze(Long orderId, FreezeRequest request) {
272	        String fp = FingerprintUtil.fingerprint(new FreezeFingerprint(request.requestId(), orderId));
273	        Object replay = replayIfSame(request.requestId(), BIZ_FREEZE, fp);
274	        if (replay != null) {
275	            return (ScheduleView) replay;
276	        }
277	
278	        OrderRow order = requireOrder(orderId);
279	        if (order.status().equals(ScheduleStatus.FROZEN.name())) {
280	            // 终态重复冻结：幂等成功，不重复写状态。
281	            ScheduleView view = buildView(order);
282	            saveIdempotent(request.requestId(), BIZ_FREEZE, fp, 200, FingerprintUtil.toJson(view));
283	            return view;
284	        }
285	        if (!order.status().equals(ScheduleStatus.ISSUED.name())
286	                && !order.status().equals(ScheduleStatus.EXECUTING.name())) {
287	            throw new BusinessException(HttpStatus.BAD_REQUEST,
288	                    "仅下达/执行中的排产单可日终冻结，当前状态为 " + order.status());
289	        }
290	
291	        LocalDateTime now = LocalDateTime.now(clock);
292	        repo.markFrozen(orderId, now);
293	        ScheduleView view = buildView(requireOrder(orderId));
294	        saveIdempotent(request.requestId(), BIZ_FREEZE, fp, 200, FingerprintUtil.toJson(view));
295	        return view;
296	    }
297	
298	    @Transactional(readOnly = true)
299	    public ScheduleView get(Long orderId) {
300	        return buildView(requireOrder(orderId));
301	    }
302	
303	    // ---------------- 内部方法 ----------------
304	
305	    private OrderRow requireOrder(long orderId) {
306	        OrderRow order = repo.findOrderById(orderId);
307	        if (order == null) {
308	            throw new BusinessException(HttpStatus.NOT_FOUND, "排产单不存在: " + orderId);
309	        }
310	        return order;
311	    }
312	
313	    private OrderRow findOrderByLineAndContract(String lineCode, String contractNo) {
314	        Long effectiveId = repo.findEffectiveOrderId(lineCode);
315	        if (effectiveId != null) {
316	            ItemRow item = repo.findItemByContract(effectiveId, contractNo);
317	            if (item != null) {
318	                return repo.findOrderById(effectiveId);
319	            }
320	        }
321	        return null;
322	    }
323	
324	    /**
325	     * 构造“合同号＋道次”重复回传的幂等视图并登记本次 requestId 的幂等记录。
326	     */
327	    private ActualResultView dedupActualView(String requestId, String fp, ActualRow existing) {
328	        OrderRow order = requireOrder(existing.orderId());
329	        ItemRow item = repo.findItemByContract(existing.orderId(), existing.contractNo());
330	        BigDecimal total = item == null ? null
331	                : repo.sumActualKmForCampaign(existing.orderId(), item.campaignNo());
332	        ActualResultView view = new ActualResultView(existing.contractNo(), existing.passNo(),
333	                existing.rollingKm(), false, false, item == null ? null : item.campaignNo(),
334	                total, order.locked(), order.rollChangeRequired(), existing.recordedAt());
335	        saveIdempotent(requestId, BIZ_ACTUAL, fp, 200, FingerprintUtil.toJson(view));
336	        return view;
337	    }
338	
339	    /**
340	     * 同键重放：指纹一致返回首次响应；同键异参抛 409 且不产生任何写入。
341	     *
342	     * @return 首次响应对象；null 表示该 requestId 首次出现
343	     */
344	    private Object replayIfSame(String requestId, String bizType, String fingerprint) {
345	        IdempotentRow row = repo.findIdempotent(requestId);
346	        if (row == null) {
347	            return null;
348	        }
349	        if (!row.fingerprint().equals(fingerprint) || !row.bizType().equals(bizType)) {
350	            throw new ConflictException(HttpStatus.CONFLICT,
351	                    "requestId " + requestId + " 已用于不同业务参数的请求，拒绝执行且不产生新版本");
352	        }
353	        return switch (bizType) {
354	            case BIZ_ACTUAL -> FingerprintUtil.fromJson(row.responseBody(), ActualResultView.class);
355	            default -> FingerprintUtil.fromJson(row.responseBody(), ScheduleView.class);
356	        };
357	    }
358	
359	    private void saveIdempotent(String requestId, String bizType, String fingerprint,
360	                                int httpStatus, String body) {
361	        boolean inserted = repo.tryInsertIdempotent(requestId, bizType, fingerprint, httpStatus, body,
362	                LocalDateTime.now(clock));
363	        if (!inserted) {
364	            // 并发同键首调竞争：唯一约束裁决后本事务所有写入将随异常回滚，
365	            // 不产生新版本；客户端用相同 requestId 重放即可取得首次结果。
366	            throw new ConflictException(HttpStatus.CONFLICT,
367	                    "requestId " + requestId + " 正在被并发处理，唯一记录已存在，请用相同参数重放");
368	        }
369	    }
370	
371	    private ScheduleView buildView(OrderRow order) {
372	        List<ItemView> items = repo.findItemsByOrderId(order.id()).stream()
373	                .map(i -> new ItemView(i.seq(), i.campaignNo(), i.seqInCampaign(), i.contractNo(),
374	                        i.widthMm(), i.rollingKm(), i.warmup(), i.locked(), i.startTime(), i.endTime()))
375	                .toList();
376	        List<WindowView> windows = repo.findWindowsByOrderId(order.id()).stream()
377	                .map(w -> new WindowView(w.campaignNo(), w.startTime(), w.endTime()))
378	                .toList();
379	        return new ScheduleView(order.id(), order.lineCode(), order.unitCode(), order.versionNo(),
380	                order.baseVersionId(), order.status(), order.effective(), order.locked(),
381	                order.rollChangeRequired(), order.frozenAt(), items, windows);
382	    }
383	
384	    /** 下达指纹载体：覆盖 requestId 与目标排产单。 */
385	    private record IssueFingerprint(String requestId, Long orderId) {
386	    }
387	
388	    /** 冻结指纹载体：覆盖 requestId 与目标排产单。 */
389	    private record FreezeFingerprint(String requestId, Long orderId) {
390	    }
391	}
