3	import com.fasterxml.jackson.core.JsonProcessingException;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import com.fasterxml.jackson.databind.SerializationFeature;
6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
7	
8	import java.security.MessageDigest;
9	import java.security.NoSuchAlgorithmException;
10	import java.util.HexFormat;
11	
12	/**
13	 * 幂等指纹工具：指纹覆盖 requestId 与全部业务字段，使用规范化 JSON 的 SHA-256。
14	 */
15	public final class FingerprintUtil {
16	
17	    private static final ObjectMapper CANONICAL = new ObjectMapper()
18	            .registerModule(new JavaTimeModule())
19	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
20	            .enable(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS);
21	
22	    private FingerprintUtil() {
23	    }
24	
25	    /**
26	     * 计算业务请求对象的指纹（SHA-256，64 位十六进制）。
27	     */
28	    public static String fingerprint(Object request) {
29	        try {
30	            byte[] json = CANONICAL.writeValueAsBytes(request);
31	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
