                                                      List<ScheduleItemRequest> items) {
        ScheduleView draft = service.createOrRevise(simpleOrder(requestId, line, items));
        service.validate(draft.id());
        return service.issue(draft.id(), new IssueRequest("issue-" + requestId));
    }

