17	    @Test
18	    void 实绩按合同号与道次去重() {
19	        draftThenValidateThenIssue("req-s", "L1",
20	                items(item("C1", 1250, "3", true, 0), item("C2", 1200, "3", false, 1)));
21	
22	        var pass1a = service.reportActual(actual("a-1", "L1", "C1", 1, "3"));
23	        var pass2 = service.reportActual(actual("a-2", "L1", "C1", 2, "3"));
24	        var pass1b = service.reportActual(actual("a-1-replay", "L1", "C1", 1, "3"));
