26	        assertThat(pass1a.accepted()).isTrue();
27	        assertThat(pass2.accepted()).isTrue();
28	        assertThat(pass1b.accepted()).isFalse();
29	        assertThat(pass1b.rollingKm()).isEqualByComparingTo("3");
30	        assertThat(jdbc.queryForObject(
31	                "SELECT COUNT(1) FROM actual_result WHERE contract_no = 'C1'", Integer.class)).isEqualTo(2);
32	    }
