34	    @Test
35	    void 实绩按道次归位到换辊周期并分别累计() {
36	        // C1/C2 在周期1，窗口 [02:00,03:00)，C3/C4 在周期2，宽度重新由宽到窄。
37	        var order = createRequest("req-camp", "L2", "U1", null, items(
