39	                item("C2", 1200, "2", false, 1),
40	                item("C3", 1250, "2", true, 3),
41	                item("C4", 1200, "2", true, 4)),
42	                List.of(window(2, 3)));
43	        ScheduleView view = service.createOrRevise(order);
44	        service.validate(view.id());
45	        service.issue(view.id(), new com.example.starter.rolling.api.dto.IssueRequest("req-camp-i"));
46	
47	        var r1 = service.reportActual(actual("c-a1", "L2", "C1", 1, "6"));
48	        assertThat(r1.campaignNo()).isEqualTo(1);
49	        assertThat(r1.campaignTotalKm()).isEqualByComparingTo("6");
50	        assertThat(r1.locked()).isFalse();
51	
