81	        assertThat(jdbc.queryForObject(
82	                "SELECT locked FROM schedule_item WHERE contract_no = 'C1'", Boolean.class)).isFalse();
83	        assertThat(jdbc.queryForObject(
84	                "SELECT locked FROM schedule_item WHERE contract_no = 'C2'", Boolean.class)).isFalse();
85	        assertThat(jdbc.queryForObject(
86	                "SELECT locked FROM schedule_item WHERE contract_no = 'C3'", Boolean.class)).isTrue();
