108	    @Test
109	    void 冻结后迟到实绩只登记事件不改冻结结论() {
110	        ScheduleView issued = draftThenValidateThenIssue("req-late", "L5", items(
111	                item("C1", 1250, "4", true, 0),
112	                item("C2", 1200, "4", false, 1)));
113	        // 冻结前累计仅 6 公里，未触发换辊阈值。
114	        service.reportActual(actual("lt-1", "L5", "C1", 1, "6"));
115	        service.freeze(issued.id(), new FreezeRequest("lt-fz"));
116	
117	        // 迟到的 5 公里即使累计会超 10，也只登记事件：冻结里程与换辊结论保持冻结时状态。
118	        var late = service.reportActual(actual("lt-2", "L5", "C2", 1, "5", T0.plusDays(1)));
