1	package com.example.starter.rolling.service;
2	
3	import com.example.starter.rolling.api.dto.RollWindowRequest;
4	import com.example.starter.rolling.api.dto.ScheduleItemRequest;
5	
6	import java.math.BigDecimal;
7	import java.util.ArrayList;
8	import java.util.HashMap;
9	import java.util.HashSet;
10	import java.util.List;
11	import java.util.Map;
12	import java.util.Set;
13	
14	/**
15	 * 排产单纯规则校验器（不访问数据库）。
16	 *
17	 * <p>规则汇总：</p>
18	 * <ul>
19	 *   <li>同一轧辊周期（两次换辊之间）内宽度按“宽→窄”渐变，相邻宽度恰跳一档合法，跳两档及以上或由窄变宽违例；</li>
20	 *   <li>同宽度连续轧制里程不得超过 10 公里，恰达 10 公里合法，超出须先排换辊；换辊重置周期累计；</li>
21	 *   <li>烫辊材只能在换辊后前 5 块，恰第 5 块为最后烫辊位；</li>
22	 *   <li>作业与换辊窗口均按半开区间 [start,end) 判定，端点相接不冲突，内部重叠冲突；</li>
23	 *   <li>宽度必须存在于合成档位表；换辊窗口必须落在作业之前或相邻作业间隙中。</li>
24	 * </ul>
25	 */
26	public final class ScheduleValidator {
27	
28	    /** 同宽度连续轧制里程上限（公里），恰达合法。 */
29	    public static final BigDecimal MAX_SAME_WIDTH_KM = BigDecimal.TEN;
30	
31	    /** 换辊后允许排入烫辊材的块位数，恰第 5 块为最后烫辊位。 */
32	    public static final int MAX_WARMUP_POSITION = 5;
33	
34	    private ScheduleValidator() {
35	    }
36	
37	    /**
38	     * 校验后的块：携带换辊周期号与周期内块序。
39	     */
40	    public record ValidatedItem(ScheduleItemRequest item, int seq, int campaignNo, int seqInCampaign) {
41	    }
42	
43	    /**
44	     * 校验结果：valid 为 true 时 items 携带周期编号可直接持久化；否则 violations 含全部违例明细。
45	     */
46	    public record Result(boolean valid, List<ValidatedItem> items, List<String> violations) {
47	    }
48	
49	    /**
50	     * 执行整单校验，收集全部违例，不做短路。
51	     *
52	     * @param items   作业列表，顺序即轧制块序（从 1 开始）
53	     * @param windows 换辊窗口列表
54	     * @param grades  板宽毫米 -> 档位号（档位号越大板越窄）
55	     */
56	    public static Result validate(List<ScheduleItemRequest> items,
57	                                  List<RollWindowRequest> windows,
58	                                  Map<Integer, Integer> grades) {
59	        List<String> violations = new ArrayList<>();
60	
61	        checkDuplicateContracts(items, violations);
62	        checkItemIntervals(items, violations);
63	        checkWindowIntervals(windows, violations);
64	        checkWidthsExist(items, grades, violations);
65	        checkItemOverlaps(items, violations);
66	        checkWindowOverlaps(windows, violations);
67	        checkWindowItemOverlaps(items, windows, violations);
68	        checkWindowPlacement(items, windows, violations);
69	
70	        List<ValidatedItem> validated = assignCampaigns(items, windows);
71	        checkCampaignRules(validated, grades, violations);
72	
73	        return new Result(violations.isEmpty(), List.copyOf(validated), List.copyOf(violations));
74	    }
75	
76	    private static void checkDuplicateContracts(List<ScheduleItemRequest> items, List<String> violations) {
77	        Set<String> seen = new HashSet<>();
78	        for (int i = 0; i < items.size(); i++) {
79	            String contract = items.get(i).contractNo();
80	            if (!seen.add(contract)) {
81	                violations.add("第" + (i + 1) + "块合同号 " + contract + " 在排产单内重复");
82	            }
83	        }
84	    }
85	
86	    private static void checkItemIntervals(List<ScheduleItemRequest> items, List<String> violations) {
87	        for (int i = 0; i < items.size(); i++) {
88	            ScheduleItemRequest item = items.get(i);
89	            if (!item.startTime().isBefore(item.endTime())) {
90	                violations.add("第" + (i + 1) + "块（合同 " + item.contractNo()
91	                        + "）作业区间非法，开始时刻必须早于结束时刻");
92	            }
93	        }
94	    }
95	
96	    private static void checkWindowIntervals(List<RollWindowRequest> windows, List<String> violations) {
97	        for (int i = 0; i < windows.size(); i++) {
98	            RollWindowRequest window = windows.get(i);
99	            if (!window.startTime().isBefore(window.endTime())) {
100	                violations.add("第" + (i + 1) + "个换辊窗口区间非法，开始时刻必须早于结束时刻");
101	            }
102	        }
103	    }
104	
105	    private static void checkWidthsExist(List<ScheduleItemRequest> items,
106	                                         Map<Integer, Integer> grades,
107	                                         List<String> violations) {
108	        for (int i = 0; i < items.size(); i++) {
109	            ScheduleItemRequest item = items.get(i);
110	            if (!grades.containsKey(item.widthMm())) {
111	                violations.add("第" + (i + 1) + "块（合同 " + item.contractNo()
112	                        + "）板宽 " + item.widthMm() + " 毫米不在合成宽度档位表中");
113	            }
114	        }
115	    }
116	
117	    private static void checkItemOverlaps(List<ScheduleItemRequest> items, List<String> violations) {
118	        // 任意两块作业时间内部重叠即冲突（半开区间 [start,end)：a.start < b.end 且 b.start < a.end）；
119	        // 端点相接合法。按合同对去重报告，避免同一对报两次。
120	        for (int i = 0; i < items.size(); i++) {
121	            for (int j = i + 1; j < items.size(); j++) {
122	                ScheduleItemRequest a = items.get(i);
123	                ScheduleItemRequest b = items.get(j);
124	                if (a.startTime().isBefore(b.endTime()) && b.startTime().isBefore(a.endTime())) {
125	                    violations.add("第" + (i + 1) + "块（合同 " + a.contractNo() + "）与第" + (j + 1)
126	                            + "块（合同 " + b.contractNo() + "）作业时间内部重叠，半开区间端点相接才合法");
127	                }
128	            }
129	        }
130	    }
131	
132	    private static void checkWindowOverlaps(List<RollWindowRequest> windows, List<String> violations) {
133	        List<RollWindowRequest> sorted = windows.stream().sorted(java.util.Comparator
134	                .comparing(RollWindowRequest::startTime)).toList();
135	        for (int i = 1; i < sorted.size(); i++) {
136	            if (sorted.get(i - 1).endTime().isAfter(sorted.get(i).startTime())) {
137	                violations.add("换辊窗口之间存在内部重叠，半开区间端点相接才合法");
138	            }
139	        }
140	    }
141	
142	    private static void checkWindowItemOverlaps(List<ScheduleItemRequest> items,
143	                                                List<RollWindowRequest> windows,
144	                                                List<String> violations) {
145	        for (int w = 0; w < windows.size(); w++) {
146	            RollWindowRequest window = windows.get(w);
147	            for (int i = 0; i < items.size(); i++) {
148	                ScheduleItemRequest item = items.get(i);
149	                // 内部重叠：window.start < item.end 且 item.start < window.end
150	                if (window.startTime().isBefore(item.endTime())
151	                        && item.startTime().isBefore(window.endTime())) {
152	                    violations.add("第" + (w + 1) + "个换辊窗口与第" + (i + 1) + "块（合同 "
153	                            + item.contractNo() + "）作业时间内部重叠");
154	                }
155	            }
156	        }
157	    }
158	
159	    private static void checkWindowPlacement(List<ScheduleItemRequest> items,
160	                                             List<RollWindowRequest> windows,
161	                                             List<String> violations) {
162	        if (items.isEmpty()) {
163	            return;
164	        }
165	        for (int w = 0; w < windows.size(); w++) {
166	            if (!fitsTimeline(items, windows.get(w))) {
167	                violations.add("第" + (w + 1)
168	                        + "个换辊窗口未落在首块之前或相邻作业的间隙中（半开区间端点相接合法），其后也无轧制作业");
169	            }
170	        }
171	    }
172	
173	    /**
174	     * 窗口落在时间轴合法位置：首块之前（window.end <= first.start），
175	     * 或第 i 块与第 i+1 块之间（item[i].end <= window.start 且 window.end <= item[i+1].start）。
176	     */
177	    private static boolean fitsTimeline(List<ScheduleItemRequest> items, RollWindowRequest window) {
178	        if (!window.endTime().isAfter(items.get(0).startTime())) {
179	            return true;
180	        }
181	        for (int i = 0; i + 1 < items.size(); i++) {
182	            if (!items.get(i).endTime().isAfter(window.startTime())
183	                    && !window.endTime().isAfter(items.get(i + 1).startTime())) {
184	                return true;
185	            }
186	        }
187	        return false;
188	    }
189	
190	    private static List<ValidatedItem> assignCampaigns(List<ScheduleItemRequest> items,
191	                                                       List<RollWindowRequest> windows) {
192	        Map<Integer, Integer> seqInCampaign = new HashMap<>();
193	        List<ValidatedItem> result = new ArrayList<>();
194	        for (int i = 0; i < items.size(); i++) {
195	            ScheduleItemRequest item = items.get(i);
196	            int campaignNo = 1;
197	            for (RollWindowRequest window : windows) {
198	                if (!window.endTime().isAfter(item.startTime())) {
199	                    campaignNo++;
200	                }
201	            }
202	            int seq = seqInCampaign.merge(campaignNo, 1, Integer::sum);
203	            result.add(new ValidatedItem(item, i + 1, campaignNo, seq));
204	        }
205	        return result;
206	    }
207	
208	    private static void checkCampaignRules(List<ValidatedItem> items,
209	                                           Map<Integer, Integer> grades,
210	                                           List<String> violations) {
211	        // 按周期分组但保持块序，逐周期检查宽度渐变、同宽里程与烫辊位。
212	        Map<Integer, Integer> previousGrade = new HashMap<>();
213	        Map<Integer, Integer> previousWidth = new HashMap<>();
214	        Map<Integer, BigDecimal> sameWidthKm = new HashMap<>();
215	
216	        for (ValidatedItem vi : items) {
217	            ScheduleItemRequest item = vi.item();
218	            int campaign = vi.campaignNo();
219	            Integer grade = grades.get(item.widthMm());
220	            if (grade == null) {
221	                continue; // 不存在的档位已在 checkWidthsExist 中报告
222	            }
223	
224	            if (vi.seqInCampaign() > MAX_WARMUP_POSITION && item.warmup()) {
225	                violations.add("第" + vi.seq() + "块（合同 " + item.contractNo()
226	                        + "）为烫辊材，但位于换辊周期 " + campaign + " 的第 " + vi.seqInCampaign()
227	                        + " 块，烫辊材须在换辊后前 " + MAX_WARMUP_POSITION + " 块排入");
228	            }
229	
230	            Integer prevGrade = previousGrade.get(campaign);
231	            if (prevGrade != null) {
232	                if (grade < prevGrade) {
233	                    violations.add("第" + vi.seq() + "块（合同 " + item.contractNo() + "）板宽 "
234	                            + item.widthMm() + " 毫米较前块变宽，轧辊周期内宽度须按宽→窄渐变");
235	                } else if (grade - prevGrade > 1) {
236	                    violations.add("第" + vi.seq() + "块（合同 " + item.contractNo() + "）板宽由档位 "
237	                            + prevGrade + " 跳到档位 " + grade + "，相邻宽度跳档不得超过一级");
238	                }
239	            }
240	
241	            BigDecimal running;
242	            if (Integer.valueOf(item.widthMm()).equals(previousWidth.get(campaign))) {
243	                running = sameWidthKm.get(campaign).add(item.rollingKm());
244	            } else {
245	                running = item.rollingKm();
246	            }
247	            sameWidthKm.put(campaign, running);
248	            if (running.compareTo(MAX_SAME_WIDTH_KM) > 0) {
249	                violations.add("第" + vi.seq() + "块（合同 " + item.contractNo() + "）使板宽 "
250	                        + item.widthMm() + " 毫米连续轧制里程达 " + running.stripTrailingZeros().toPlainString()
251	                        + " 公里，超过轧辊周期上限 " + MAX_SAME_WIDTH_KM + " 公里，须先排换辊");
252	            }
253	
254	            previousGrade.put(campaign, grade);
255	            previousWidth.put(campaign, item.widthMm());
256	        }
257	    }
258	}
