1	package com.example.starter.rolling.repo;
2	
3	import org.springframework.jdbc.core.JdbcTemplate;
4	import org.springframework.stereotype.Repository;
5	import org.springframework.transaction.annotation.Propagation;
6	import org.springframework.transaction.annotation.Transactional;
7	
8	/**
9	 * 主键分配：基于 id_alloc 表的原子更新取号，避免跨库自增差异；
10	 * 每次取号独立事务提交，保证并发调用不重号。
11	 */
12	@Repository
13	public class IdAllocator {
14	
15	    private static final String SEQ_NAME = "global";
16	
17	    private final JdbcTemplate jdbc;
18	
19	    public IdAllocator(JdbcTemplate jdbc) {
20	        this.jdbc = jdbc;
21	    }
22	
23	    /**
24	     * 分配一个新主键。
25	     */
26	    @Transactional(propagation = Propagation.REQUIRES_NEW)
27	    public long nextId() {
28	        return nextIds(1).start();
29	    }
30	
31	    /**
32	     * 一次分配 n 个连续主键，返回 [start, start+n) 区间。
33	     */
34	    @Transactional(propagation = Propagation.REQUIRES_NEW)
35	    public IdRange nextIds(int n) {
36	        int updated = jdbc.update(
37	                "UPDATE id_alloc SET next_val = next_val + ? WHERE seq_name = ?", n, SEQ_NAME);
38	        if (updated == 0) {
39	            throw new IllegalStateException("id_alloc 缺少序列行: " + SEQ_NAME);
40	        }
41	        Long after = jdbc.queryForObject(
42	                "SELECT next_val FROM id_alloc WHERE seq_name = ?", Long.class, SEQ_NAME);
43	        if (after == null) {
44	            throw new IllegalStateException("id_alloc 序列行丢失: " + SEQ_NAME);
45	        }
