-- 轧辊寿命台账：roll_no 轧辊号；cycle_limit_km 周期上限（公里）；
-- total_km 累计里程（公里），与实绩入库同事务更新；coils_used 上机后已轧卷数（前 5 卷为首用烫辊位）；
-- on_machine=1 表示当前在机；banned=1 表示累计里程达周期上限立即禁排；
-- frozen_at 非空表示日冻结时刻，冻结后迟到实绩只记事件不改里程。
CREATE TABLE IF NOT EXISTS roll_ledger (
    roll_no VARCHAR(32) NOT NULL PRIMARY KEY,
    cycle_limit_km DECIMAL(10,3) NOT NULL,
    total_km DECIMAL(10,3) NOT NULL DEFAULT 0,
    coils_used INT NOT NULL DEFAULT 0,
    on_machine TINYINT NOT NULL DEFAULT 0,
    banned TINYINT NOT NULL DEFAULT 0,
    frozen_at TIMESTAMP NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 换辊实绩：按“轧辊号＋实绩时刻”唯一去重，乱序回传按 recorded_at 归位；
-- first_use=1 表示新辊上机后前 5 卷的首用标记。
CREATE TABLE IF NOT EXISTS roll_change_actual (
